INSERT INTO posts (slug, title, excerpt, body, tags, reading_minutes, media_id, published_on) VALUES ('glycemic-index-and-load-explained', '{"en": "Glycemic Index and Glycemic Load, Explained Simply", "bn": "গ্লাইসেমিক ইনডেক্স আর গ্লাইসেমিক লোড, সহজ ভাষায়"}'::jsonb, '{"en": "The glycemic index tells you how fast a food raises blood sugar; the glycemic load also counts how much you eat. Here is how to read both numbers.", "bn": "গ্লাইসেমিক ইনডেক্স বলে কোনো খাবার কত দ্রুত রক্তে চিনি বাড়ায়; গ্লাইসেমিক লোড এর সাথে কতটা খাচ্ছেন সেটাও হিসাব করে। দুটো সংখ্যা কীভাবে বুঝবেন, দেখে নিন।"}'::jsonb, '{"en": ["If you have diabetes or are watching your blood sugar, you may have heard doctors and dietitians talk about the glycemic index. It is a useful idea, but it is easy to misread. This short guide explains what the numbers mean and how to use them at the dinner table.", "## What the glycemic index (GI) is", "The glycemic index ranks foods that contain carbohydrate by how quickly they raise blood sugar compared with pure glucose, which is set at 100. A food with a high GI is digested fast and causes a quicker rise. A food with a low GI is digested more slowly and gives a gentler rise.", "- Low GI: 55 or less", "- Medium GI: 56 to 69", "- High GI: 70 or more", "## Some everyday foods", "According to Harvard Health''s GI table, boiled white rice has a GI of about 73, red or brown rice about 68, chapati (ruti) about 52, and lentils about 32. So a bowl of dal sits much lower on the scale than a plate of white rice.", "## What glycemic load (GL) adds", "GI only tells you how fast. It does not tell you how much carbohydrate is in the portion you actually eat. Glycemic load combines both: GL = GI × available carbohydrate in the portion (in grams) ÷ 100.", "- Low GL: 10 or less", "- Medium GL: 11 to 19", "- High GL: 20 or more", "This is why portion size matters. A small serving of a high-GI food can have a moderate load, while a large plate of the same food can have a high load.", "## Using it at home", "- Keep rice portions modest and fill more of the plate with vegetables and dal.", "- Try red rice or ruti in place of some white rice.", "- Add protein such as fish, egg or dal to every meal.", "GI values change with the variety of the food, the cooking time and what else is on the plate, so treat them as a rough guide, not exact numbers. If you take medicine for diabetes, talk to your doctor or dietitian before making big changes to your meals."], "bn": ["আপনার যদি ডায়াবেটিস থাকে বা রক্তে চিনির দিকে খেয়াল রাখেন, তাহলে ডাক্তার বা পুষ্টিবিদের মুখে গ্লাইসেমিক ইনডেক্সের কথা হয়তো শুনেছেন। ধারণাটা কাজের, তবে ভুল বোঝাও সহজ। এই ছোট লেখায় সংখ্যাগুলোর মানে আর খাবার টেবিলে সেগুলো কীভাবে কাজে লাগাবেন, তা বলা হলো।", "## গ্লাইসেমিক ইনডেক্স (জিআই) কী", "শর্করাযুক্ত খাবার খাওয়ার পর রক্তে চিনি কত দ্রুত বাড়ে, সেটা খাঁটি গ্লুকোজের (যার মান ১০০ ধরা হয়) সাথে তুলনা করে গ্লাইসেমিক ইনডেক্স ঠিক করা হয়। উচ্চ জিআইয়ের খাবার দ্রুত হজম হয় আর রক্তে চিনি তাড়াতাড়ি বাড়ায়। নিম্ন জিআইয়ের খাবার ধীরে হজম হয়, চিনিও ধীরে বাড়ে।", "- নিম্ন জিআই: ৫৫ বা তার কম", "- মাঝারি জিআই: ৫৬ থেকে ৬৯", "- উচ্চ জিআই: ৭০ বা তার বেশি", "## রোজকার কিছু খাবার", "হার্ভার্ড হেলথের জিআই তালিকা অনুযায়ী সেদ্ধ সাদা ভাতের জিআই প্রায় ৭৩, লাল চালের ভাত প্রায় ৬৮, চাপাতি (রুটি) প্রায় ৫২ আর ডাল প্রায় ৩২। অর্থাৎ এক বাটি ডাল এক প্লেট সাদা ভাতের চেয়ে অনেক নিচে থাকে।", "## গ্লাইসেমিক লোড (জিএল) বাড়তি কী বলে", "জিআই শুধু বলে কত দ্রুত। আপনি আসলে যতটুকু খাচ্ছেন তাতে কতটা শর্করা আছে, তা বলে না। গ্লাইসেমিক লোড দুটোকে একসাথে ধরে: জিএল = জিআই × ওই পরিমাণ খাবারে পাওয়া শর্করা (গ্রামে) ÷ ১০০।", "- নিম্ন জিএল: ১০ বা তার কম", "- মাঝারি জিএল: ১১ থেকে ১৯", "- উচ্চ জিএল: ২০ বা তার বেশি", "এ কারণেই পরিমাণ গুরুত্বপূর্ণ। উচ্চ জিআইয়ের খাবার অল্প খেলে লোড মাঝারি হতে পারে, আবার একই খাবার বড় প্লেটে খেলে লোড বেশি হয়।", "## ঘরে কীভাবে কাজে লাগাবেন", "- ভাতের পরিমাণ পরিমিত রাখুন, প্লেটের বেশি অংশ সবজি আর ডাল দিয়ে ভরুন।", "- কিছু সাদা ভাতের বদলে লাল চালের ভাত বা রুটি খেয়ে দেখুন।", "- প্রতি বেলায় মাছ, ডিম বা ডালের মতো আমিষ রাখুন।", "খাবারের জাত, রান্নার সময় আর প্লেটে আর কী আছে তার ওপর জিআই বদলায়, তাই এগুলোকে মোটামুটি ধারণা হিসেবে নিন, একেবারে নির্দিষ্ট সংখ্যা হিসেবে নয়। ডায়াবেটিসের ওষুধ খেলে খাবারে বড় কোনো পরিবর্তনের আগে আপনার ডাক্তার বা পুষ্টিবিদের সাথে কথা বলুন।"]}'::jsonb, '["glycemic-index", "glycemic-load", "diabetes", "rice", "carbohydrates"]'::jsonb, 3, (SELECT id FROM media WHERE source_url = 'asset:photos/post-glycemic-index-and-load-explained.webp'), '2026-11-15') ON CONFLICT (slug) DO NOTHING;
